const $=s=>document.querySelector(s), main=$('#main');let storageOK=true;let progress={lesson:false,lab:false,quiz:false,score:0};try{const p=JSON.parse(localStorage.getItem('geneed-v1'));if(p&&typeof p==='object')for(const k of Object.keys(progress))if(typeof p[k]===typeof progress[k])progress[k]=p[k]}catch{storageOK=false}function save(){try{localStorage.setItem('geneed-v1',JSON.stringify(progress))}catch{storageOK=false}}let step=0,paired=false,question=0,answers=[],checked=false;const questions=[{q:'Which base pairs with adenine (A) in DNA?',options:['Cytosine (C)','Thymine (T)','Guanine (G)'],correct:1,why:'In DNA, adenine pairs with thymine. Cytosine pairs with guanine.'},{q:'For a Pp × Pp pea flower cross, what is the probability of white flowers?',options:['25%','50%','75%'],correct:0,why:'Only pp produces white flowers in this simple model. One of the four equally likely combinations is pp.'},{q:'What does heterozygous mean?',options:['Two identical alleles','Two different alleles at a locus','An allele that is always more common'],correct:1,why:'Pp is heterozygous: it has two different alleles. Dominant does not mean more common or better.'},{q:'Will every four offspring from Pp × Pp include exactly one pp offspring?',options:['Yes, the square guarantees it','No, each offspring is an independent outcome'],correct:1,why:'25% is a probability for each offspring. Small groups can differ from the expected ratio.'}];const helix=`<div class="dna-art" aria-hidden="true"><svg viewBox="0 0 240 270"><g fill="none" stroke-linecap="round">${Array.from({length:14},(_,i)=>{const y=18+i*18,x=120-55*Math.cos((y-15)/240*Math.PI*2);return `<path d="M${x} ${y} L${240-x} ${y}" stroke="${i%2?'#d6c1e7':'#faf8e7'}" stroke-width="8"/>`}).join('')}${[0,1].map(n=>`<path d="${Array.from({length:81},(_,i)=>{const y=15+i*3,x=120+(n?1:-1)*55*Math.cos(i/80*Math.PI*2);return `${i?'L':'M'}${x} ${y}`}).join(' ')}" stroke="${n?'#96b96e':'#37694b'}" stroke-width="11"/>`).join('')}</g></svg><span class="floating one">A + T &nbsp; · &nbsp; C + G</span><span class="floating two">Small building blocks. Big discoveries.</span></div>`;function title(k,h,p){return `<div class="intro"><div><span class="kicker">${k}</span><h1>${h}</h1><p>${p}</p></div><span class="pill">Introductory genetics</span></div>`}function dashboard(){const done=Number(progress.lesson)+Number(progress.lab)+Number(progress.quiz);return `${title('YOUR NEXT DISCOVERY','Hello, Alex. Let’s get curious.','Big ideas start with small discoveries. Pick up where you left off.')}<section class="hero"><div class="hero-copy"><span class="kicker">FOUNDATION 01 &nbsp; / &nbsp; INTERACTIVE LESSON</span><h2>A tiny molecule.<br>A whole world of possibility.</h2><p>Meet DNA: the instructions behind living things. Explore its structure, one base pair at a time.</p><a class="button" href="#lesson">${progress.lesson?'Revisit lesson':'Explore DNA fundamentals'} &nbsp; →</a><small>8 min · Beginner friendly</small></div>${helix}</section><div class="stats"><div class="stat"><span class="stat-icon">▤</span><div><strong>${done}<span style="font-size:14px;color:var(--muted)"> / 3</span></strong><small>Activities completed</small></div></div><div class="stat"><span class="stat-icon">✧</span><div><strong>${progress.quiz?progress.score+'/4':'—'}</strong><small>Latest quiz score</small></div></div><div class="stat"><span class="stat-icon">❋</span><div><strong>${progress.quiz&&progress.score>=3?'1':'0'}</strong><small>Discovery badges</small></div></div></div><div class="section-head"><h2>Your discovery path</h2><p>Learn → Experiment → Reflect</p></div><section class="cards">${[['01','DNA fundamentals','Build an understanding of DNA, genes, and alleles.','lesson','⌁','8 min · Interactive lesson',progress.lesson],['02','Patterns of inheritance','Cross pea plants and discover how traits are passed on.','simulator','⚗','6 min · Virtual experiment',progress.lab],['03','Put curiosity to the test','Check your understanding with four short questions.','quiz','✧','4 min · Knowledge check',progress.quiz]].map(x=>`<article class="card"><div class="card-visual" aria-hidden="true">${x[4]}</div><span class="meta">${x[0]} / ${x[5]}</span><h3>${x[1]}</h3><p>${x[2]}</p><div class="progress"><span style="width:${x[6]?100:0}%"></span></div><a href="#${x[3]}">${x[6]?'Completed · Revisit':'Start exploring'} →</a></article>`).join('')}</section><p class="note">Sample student profile. Activity results are ${storageOK?'saved on this browser':'available for this session; browser storage is unavailable'}. No account required.</p>`}function lesson(){const content=[`<h2>The molecule of instructions</h2><p>DNA (deoxyribonucleic acid) stores biological information in a sequence of four bases: adenine, thymine, cytosine, and guanine. Its two strands form a double helix.</p><p>The sugar–phosphate backbones form the sides; complementary bases connect the strands. In DNA, <strong>A pairs with T</strong> and <strong>C pairs with G</strong>.</p><div class="nucleotide"><span class="base">A</span><span class="base t">T</span><span class="base c">C</span><span class="base g">G</span></div><p class="note">Illustration is schematic, not a molecular scale model.</p>`,`<h2>Build a complementary strand</h2><p>One DNA strand reads <strong>5′–A C G T–3′</strong>. Which sequence pairs with it, reading the opposite strand from <strong>3′ to 5′</strong>?</p><div class="nucleotide"><span class="base">A</span><span class="base c">C</span><span class="base g">G</span><span class="base t">T</span></div><div class="choice-row"><button class="secondary" data-pair="wrong">3′–A C G T–5′</button><button class="secondary" data-pair="right">3′–T G C A–5′</button><button class="secondary" data-pair="wrong">3′–T C G A–5′</button></div><div id="pair-feedback" class="feedback" role="status">${paired?'Correct. A–T and C–G pair across strands, which run in opposite directions.':''}</div>`,`<h2>From DNA to inherited traits</h2><p>A gene is a segment of DNA that contributes to a functional product, such as a protein or RNA. Alleles are versions of DNA at a particular location.</p><p>In the diploid pea-plant model we’ll explore, an offspring inherits one allele for this gene from each parent. <strong>PP</strong> and <strong>pp</strong> are homozygous; <strong>Pp</strong> is heterozygous.</p><div class="feedback">One gene doesn’t explain every trait. Many traits involve multiple genes and environmental influences.</div>`];return `${title('FOUNDATION 01','DNA fundamentals','Get to know the building blocks of inheritance.')}<div class="lesson-tabs" aria-label="Lesson steps">${['Meet DNA','Pair the bases','Genes & alleles'].map((s,i)=>`<button data-step="${i}" ${step===i?'aria-current="step"':''}>${i+1}. ${s}</button>`).join('')}</div><section class="panel two-col"><div>${content[step]}<div class="actions">${step>0?'<button class="secondary" id="back-step">← Back</button>':''}<button id="next-step">${step<2?'Continue →':'Complete lesson ✓'}</button></div><p class="note">Step ${step+1} of 3${step===1?' · Answer the pairing activity to continue.':''}</p></div>${helix}</section>`}let trait='flower',parentA='Pp',parentB='Pp';function simulator(){let s=trait==='flower'?'P':'R',d=trait==='flower'?'Purple flowers':'Round seeds',r=trait==='flower'?'White flowers':'Wrinkled seeds';let result=GeneEngine.cross(parentA,parentB,s);const options=[s+s,s+s.toLowerCase(),s.toLowerCase()+s.toLowerCase()];return `${title('VIRTUAL LAB 01','Small crosses. New possibilities.','Explore a single-gene Mendelian cross in pea plants.')}<div class="two-col"><section class="panel"><span class="kicker">SET UP YOUR EXPERIMENT</span><h2>What will the offspring inherit?</h2><label for="trait">Pea plant trait</label><select id="trait"><option value="flower" ${trait==='flower'?'selected':''}>Flower color · purple / white</option><option value="seed" ${trait==='seed'?'selected':''}>Seed shape · round / wrinkled</option></select><div class="controls">${['A','B'].map(p=>`<div><label for="parent${p}">Parent ${p} genotype</label><select id="parent${p}">${options.map(g=>`<option ${(p==='A'?parentA:parentB)===g?'selected':''}>${g}</option>`).join('')}</select></div>`).join('')}</div><p><strong>${s}</strong> = ${d.toLowerCase()} (dominant)<br><strong>${s.toLowerCase()}</strong> = ${r.toLowerCase()} (recessive)</p><p class="note">Assumes one gene, two alleles, complete dominance, and equally likely allele segregation. Dominant does not mean stronger, better, or more common.</p><button id="record-lab">${progress.lab?'Experiment recorded ✓':'Record this experiment ✓'}</button><div id="lab-feedback" role="status"></div></section><section class="panel" aria-live="polite"><span class="kicker">PREDICTED OUTCOMES</span><h2>${parentA} × ${parentB}</h2><table class="square"><caption class="note">Each cell has a 25% probability. Columns: Parent B; rows: Parent A.</caption><thead><tr><th scope="col">A / B</th>${[...parentB].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${[...parentA].map((x,i)=>`<tr><th scope="row">${x}</th>${result.cells.slice(i*2,i*2+2).map(g=>`<td>${g}<small>${g===s.toLowerCase().repeat(2)?r:d}</small></td>`).join('')}</tr>`).join('')}</tbody></table><h3>Phenotype probabilities</h3><div class="result-row"><span>${d}</span><strong>${result.dominant}%</strong></div><div class="result-row"><span>${r}</span><strong>${result.recessive}%</strong></div><p class="note">Genotypes: ${Object.entries(result.genotypes).map(([g,n])=>`${g} ${n}%`).join(' · ')}</p><p class="note">Probabilities apply independently to each offspring. Four offspring won’t necessarily match these four cells.</p></section></div><a class="button" href="#quiz">Check your understanding →</a>`}function quiz(){if(question>=questions.length){const score=answers.filter((a,i)=>a===questions[i].correct).length;return `${title('KNOWLEDGE CHECK','Look how far you’ve come.','Every question is a chance to make a connection.')}<section class="panel"><div class="badge" aria-hidden="true">${score>=3?'✳':'⌁'}</div><h2>${score} out of 4 correct</h2><p>${score>=3?'Discovery badge earned. You’ve connected DNA basics with inheritance.':'Keep exploring. Review the explanations and try again when you’re ready.'}</p>${questions.map((q,i)=>`<div class="feedback"><strong>${i+1}. ${q.q}</strong><br>Your answer: ${q.options[answers[i]]}. ${answers[i]===q.correct?'Correct.':'Correct answer: '+q.options[q.correct]+'.'}<br>${q.why}</div>`).join('')}<div class="actions"><button id="retry">Try again</button><a class="button" href="#dashboard">Back to overview</a></div></section>`}let q=questions[question];return `${title('KNOWLEDGE CHECK','Turn discoveries into understanding.','Four questions. Immediate feedback. Room to learn.')}<section class="panel"><span class="kicker">QUESTION ${question+1} OF 4</span><div class="progress"><span style="width:${question/4*100}%"></span></div><form id="quiz-form"><fieldset><legend>${q.q}</legend>${q.options.map((o,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" required ${checked?'disabled':''} ${answers[question]===i?'checked':''}>${o}</label>`).join('')}</fieldset>${checked?`<div class="feedback" role="status"><strong>${answers[question]===q.correct?'That’s right.':'Not quite. '+q.options[q.correct]+'.'}</strong><br>${q.why}</div><button type="button" id="next-question">${question===3?'See my results':'Next question →'}</button>`:'<button type="submit">Check answer</button>'}</form></section>`}function about(){return `${title('BEHIND THE PROTOTYPE','Learning through exploration.','A working MVP built for a UX portfolio.')}<section class="panel"><h2>What works today</h2><p>Dashboard, three-step DNA lesson with a base-pair activity, two Mendelian trait examples with all parent combinations, a four-question quiz with feedback, a discovery badge, and browser-local progress.</p><h2>Demo data & planned features</h2><p>Alex Lee is a fictional sample student. There is no login, cloud sync, classroom reporting, or verified learning analytics. DNA extraction, PCR, multimedia lessons, and additional badges are future concepts and are not implemented. The dashboard shows only activity progress from this browser.</p><h2>Scientific references</h2><ul class="source-list"><li><a href="https://openstax.org/books/biology/pages/12-3-laws-of-inheritance" target="_blank" rel="noopener">OpenStax Biology: Laws of inheritance ↗</a> — pea examples, segregation, and probability.</li><li><a href="https://www.genome.gov/genetics-glossary/Deoxyribonucleic-Acid" target="_blank" rel="noopener">NHGRI: DNA ↗</a> — DNA structure and base pairing.</li><li><a href="https://www.genome.gov/genetics-glossary/Allele" target="_blank" rel="noopener">NHGRI: Allele ↗</a> — variants at a genomic location.</li></ul><p class="note">Educational simplified model. Human eye color, tongue rolling, and other complex traits are deliberately not represented as simple dominant/recessive examples.</p><button class="secondary" id="reset">Reset local demo progress</button><div id="reset-feedback" role="status"></div></section>`}function render(){const route=location.hash.slice(1)||'dashboard';const pages={dashboard,lesson,simulator,quiz,about};main.innerHTML=(pages[route]||dashboard)();$('#page-name').textContent=({dashboard:'Overview',lesson:'DNA fundamentals',simulator:'Cross simulator',quiz:'Knowledge check',about:'About the prototype'})[route]||'Overview';document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+route;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});bind()}function bind(){document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;render()});document.querySelectorAll('[data-pair]').forEach(b=>b.onclick=()=>{const right=b.dataset.pair==='right';paired=paired||right;$('#pair-feedback').textContent=right?'Correct. A–T and C–G pair across strands, which run in opposite directions.':'Try again: pair A with T, C with G, G with C, and T with A.'});if($('#next-step'))$('#next-step').onclick=()=>{if(step===1&&!paired){$('#pair-feedback').textContent='Choose the complementary sequence before continuing.';return}if(step<2){step++;render()}else{if(!paired){step=1;render();$('#pair-feedback').textContent='Complete the base-pair activity to finish this lesson.';return}progress.lesson=true;save();location.hash='simulator'}};if($('#back-step'))$('#back-step').onclick=()=>{step--;render()};if($('#trait'))$('#trait').onchange=e=>{trait=e.target.value;parentA=parentB=trait==='flower'?'Pp':'Rr';render();$('#trait').focus()};['A','B'].forEach(p=>{if($('#parent'+p))$('#parent'+p).onchange=e=>{if(p==='A')parentA=e.target.value;else parentB=e.target.value;render();$('#parent'+p).focus()}});if($('#record-lab'))$('#record-lab').onclick=()=>{progress.lab=true;save();$('#record-lab').textContent='Experiment recorded ✓';$('#lab-feedback').textContent='Saved to your learning progress. Try another cross or take the quiz.'};if($('#quiz-form'))$('#quiz-form').onsubmit=e=>{e.preventDefault();const choice=new FormData(e.target).get('answer');if(choice===null)return;answers[question]=+choice;checked=true;render();$('#next-question').focus()};if($('#next-question'))$('#next-question').onclick=()=>{question++;checked=false;if(question===4){progress.quiz=true;progress.score=answers.filter((a,i)=>a===questions[i].correct).length;save()}render();main.focus()};if($('#retry'))$('#retry').onclick=()=>{question=0;answers=[];checked=false;render()};if($('#reset'))$('#reset').onclick=()=>{progress={lesson:false,lab:false,quiz:false,score:0};question=0;answers=[];checked=false;step=0;paired=false;save();$('#reset-feedback').textContent='Demo progress reset. Your overview now starts at zero.'}}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);main.focus()});render();
